import shutil,pathlib,os,stat
src=pathlib.Path(r"{module_dir}"); dst=pathlib.Path(r"{data_dir}")/"grokbot"
dst.mkdir(parents=True,exist_ok=True)

# ---- 1. the corpus DATA: converted BIS documents, unified indexes, the FTS index -----------------
# engineering_rag_india carries the converted documents (documents/standards/<STEM>/...), the unified
# indexes (indexes/*.json) and the spec FTS (search/spec_fts.sqlite) in the repo itself. They are
# copied into the workspace as data. The query cache is not copied: retrieval rebuilds it, and its
# fingerprint covers the page markdown so a stale one would only be discarded.
for name in ("documents", "indexes", "search"):
    c = src/name
    if c.is_dir():
        shutil.copytree(c, dst/name, dirs_exist_ok=True)
        print("[is-corpus] copied", name)
    else:
        print("[is-corpus] WARNING: the checkout has no", name, "folder")

# ---- 2. the module's scripts, LAST, so code always wins over anything a data bundle carries -----
# The workspace keeps its own copy because the tabs and the grounding server run from the workspace
# and retrieval.find_root expects scripts/ beside documents/. Copied file by file with the
# read-only bit cleared, because copytree leaves a read-only destination in place without a word.
if (src/"scripts").is_dir():
    (dst/"scripts").mkdir(parents=True, exist_ok=True)
    replaced, failed = [], []
    for f in sorted((src/"scripts").rglob("*")):
        if f.is_dir() or "__pycache__" in f.parts:
            continue
        t = dst/"scripts"/f.relative_to(src/"scripts")
        t.parent.mkdir(parents=True, exist_ok=True)
        if t.is_file() and t.stat().st_size == f.stat().st_size and t.read_bytes() == f.read_bytes():
            continue
        try:
            if t.exists():
                os.chmod(t, stat.S_IWRITE | stat.S_IREAD)
            shutil.copy2(f, t)
            replaced.append(f.name)
        except OSError as e:
            failed.append(f"{f.name} ({e.__class__.__name__})")
    if replaced:
        print("[is-corpus] workspace scripts refreshed:", ", ".join(replaced))
    if failed:
        print("[is-corpus] COULD NOT REFRESH:", ", ".join(failed))
        raise SystemExit("[is-corpus] the workspace code is older than the module -- queries would use the OLD code")

# ---- 3. prove it, rather than assume it --------------------------------------------------------
stale=[]
for n in ("retrieval.py","build_index.py","search.py","query_cache.py","pipeline_fixes.py"):
    a, b = src/"scripts"/n, dst/"scripts"/n
    if not a.is_file():
        continue
    if not b.is_file() or a.read_bytes() != b.read_bytes():
        stale.append(n)
if stale:
    raise SystemExit("[is-corpus] workspace code does not match the module: " + ", ".join(stale))

for d in ("documents/standards","queue/in","queue/out","queue/done","cache"):
    (dst/d).mkdir(parents=True,exist_ok=True)
n = sum(1 for d in (dst/"documents"/"standards").iterdir() if d.is_dir()) if (dst/"documents"/"standards").is_dir() else 0
print("[is-corpus] workspace ready at", dst, "--", n, "document folders,", "FTS present" if (dst/"search"/"spec_fts.sqlite").is_file() else "NO FTS index (run Rebuild index)")

