import pathlib,sqlite3,json,sys
root=pathlib.Path(r"{data_dir}")/"grokbot"
print("workspace:", root)
std=root/"documents"/"standards"
stems=sorted(d.name for d in std.iterdir() if d.is_dir()) if std.is_dir() else []
print()
print("== converted BIS documents (documents/standards/<STEM>) ==")
print("  document folders:", len(stems))
idx=root/"indexes"/"documents.json"
meta={}
if idx.is_file():
    d=json.loads(idx.read_text(encoding="utf-8"))
    rows=d if isinstance(d,list) else list(d.values())
    for r in rows:
        if isinstance(r,dict) and r.get("id"): meta[r["id"]]=r
for s in stems:
    r=meta.get(s) or {}
    print(f"   - {s:26} edition {str(r.get('edition') or '?'):12} {str(r.get('collection_name') or ''):32} quality {r.get('quality') or '(not indexed)'}")
    for k in (r.get("known_defects") or [])[:3]: print("       !", k[:110])
print()
print("== search index ==")
f=root/"search"/"spec_fts.sqlite"
if f.is_file():
    try:
        c=sqlite3.connect(f"file:{f}?mode=ro", uri=True); n=c.execute("select count(*) from chunks").fetchone()[0]
        print(f"  spec_fts.sqlite  {n:>7} chunks   the IS documents")
    except Exception as e: print(f"  spec_fts.sqlite  present but unreadable: {e}")
else:
    print("  spec_fts.sqlite  MISSING -- run Rebuild index (or reinstall the module)")
print("  (no OpenSees / worked-example collections: the India corpus serves the IS documents only)")
print()
missing=[s for s in stems if s not in meta]
if missing: print("NOTE: folders not in indexes/documents.json (run Rebuild index):", ", ".join(missing))
if not f.is_file():
    print("NEXT: install or update the IS corpus module -- its post-install copies the documents, indexes and search")
    print("      scripts from the private engineering_rag_india checkout (git clone with your credentials, or a linked working copy).")
else:
    print("IS corpus present. The design agents ground their clauses here (RAG_API_URL).")
